import sys
sys.setrecursionlimit(200000)

def articulationPoints(V, adj):
    disc = [-1] * V
    low = [-1] * V
    parent = [-1] * V
    ap = set()
    timer = [0]

    def dfs(u):
        children = 0
        disc[u] = low[u] = timer[0]
        timer[0] += 1

        for v in adj[u]:
            if disc[v] == -1:
                children += 1
                parent[v] = u
                dfs(v)
                low[u] = min(low[u], low[v])

                if parent[u] != -1 and low[v] >= disc[u]:
                    ap.add(u)
            elif v != parent[u]:
                low[u] = min(low[u], disc[v])

        if parent[u] == -1 and children > 1:
            ap.add(u)

    for i in range(V):
        if disc[i] == -1:
            dfs(i)

    result = sorted(list(ap))
    if not result:
        return [-1]
    return result

def main():
    try:
        data = sys.stdin.read().split()
    except Exception:
        return

    if not data:
        return

    iterator = iter(data)
    try:
        V = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(V)]

    try:
        for i in range(V):
            count_str = next(iterator)
            count = int(count_str)
            for _ in range(count):
                neighbor = int(next(iterator))
                adj[i].append(neighbor)
    except StopIteration:
        pass

    result = articulationPoints(V, adj)
    print(result)

if __name__ == "__main__":
    main()
